// A kind's plan expands its effects while Kiln's compilers lower it: a named effect is emitted where it is used, every time it
// is used. The work is counted while it happens (16d review R3; chapter 16d: named-reference recursion at most 32, every
// traversed object counted once per occurrence, the plan's generated bytes at most 16 MiB), so a plan that would expand
// without end is refused with a reason before it grows, and before anything registers.
using Xunit;

namespace Kiln.BlockTests;

[Collection("block kinds")]
public sealed class KindBudgetTests
{
    private static KindApplication Submit(ModBlocks target, KindOwner consumer, BlockPlan plan) =>
        KindApply.Submit(target, consumer, plan, stage => KindDefine.HandleOf(target.Id, plan, stage));

    /// <summary>e00 is a leaf and each next effect names the one before: products are staged in key order, so every effect is
    /// staged before the one that names it and staging never nests. The primary is the last.</summary>
    private static BlockPlan Chain(BlockCompileContext c, int count)
    {
        var products = new List<BlockProduct>();
        for (var i = 0; i < count; i++)
            products.Add(c.Effect($"e{i:00}", i == 0 ? new EffectBlock { Heal = 1 } : new EffectBlock { Then = [(EffectRef)c.ProductName($"e{i - 1:00}")] }));
        return c.Plan($"e{count - 1:00}", products);
    }

    [Fact]
    public void A_chain_staged_in_dependency_order_is_bounded_while_it_expands()
    {
        using var w = new KindWorld();
        var (entry, kind, _) = KindKit.Lantern();
        var consumer = KindKit.Owner("budget-chain");
        var target = KindKit.Mod("budget-chain");
        kind.Body = (c, _) => Chain(c, 32);
        Assert.Equal(BlockApplyState.Applied, Submit(target, consumer, KindCompiler.Compile(consumer, entry, "fits", new LanternBlock())).State);
        kind.Body = (c, _) => Chain(c, 33);
        var e = Assert.Throws<BlockError>(() => Submit(target, consumer, KindCompiler.Compile(consumer, entry, "too-deep", new LanternBlock())));
        Assert.Contains($"named effects nest more than {KindCompiler.MaxDepth} deep", e.Message);
        Assert.Single(w.Created);
        Assert.False(target.Handles.ContainsKey("too-deep"));
    }

    [Fact]
    public void Effects_that_branch_are_refused_by_the_work_budget_while_they_expand()
    {
        using var w = new KindWorld();
        var (entry, kind, _) = KindKit.Lantern();
        var consumer = KindKit.Owner("budget-branch");
        var target = KindKit.Mod("budget-branch");
        // b00 heals; every next one runs the one before twice: b13 alone expands to 2^14 - 1 effects
        kind.Body = (c, _) =>
        {
            var products = new List<BlockProduct>();
            for (var i = 0; i < 14; i++)
                products.Add(c.Effect($"b{i:00}", i == 0 ? new EffectBlock { Heal = 1 }
                    : new EffectBlock { Then = [(EffectRef)c.ProductName($"b{i - 1:00}"), (EffectRef)c.ProductName($"b{i - 1:00}")] }));
            return c.Plan("b13", products);
        };
        var e = Assert.Throws<BlockError>(() => Submit(target, consumer, KindCompiler.Compile(consumer, entry, "branches", new LanternBlock())));
        Assert.Contains($"more than {KindCompiler.MaxNodes} effects", e.Message);
        Assert.Empty(w.Created);
        Assert.Empty(w.Sink.Writes);
        Assert.Null(KindBudget.Current);
    }

    [Fact]
    public void An_effect_used_in_several_places_counts_each_time_and_a_plan_within_the_budget_applies()
    {
        using var w = new KindWorld();
        var (entry, kind, _) = KindKit.Lantern();
        var consumer = KindKit.Owner("budget-shared");
        var target = KindKit.Mod("budget-shared");
        kind.Body = (c, _) => c.Plan("p", [
            c.Effect("p", new EffectBlock { Then = [.. Enumerable.Repeat((EffectRef)c.ProductName("s"), 8)] }),
            c.Effect("s", new EffectBlock { Heal = 1 }),
        ]);
        Assert.Equal(BlockApplyState.Applied, Submit(target, consumer, KindCompiler.Compile(consumer, entry, "shared", new LanternBlock())).State);
    }

    [Fact]
    public void The_bytes_a_plan_emits_are_counted_while_it_expands()
    {
        // the byte bound itself (16 MiB) is out of reach of 4096 effects; a smaller budget shows that it is counted as it grows
        using var budget = KindBudget.Open("provider:lantern bytes", maxBytes: 64);
        var b = new ProgramBuilder("p");
        b.BeginCode();
        var e = Assert.Throws<BlockError>(() =>
        {
            for (var i = 0; i < 100; i++)
            {
                b.VInt($"v{i}", i);
                budget.Enter("provider:lantern bytes", $"effects[{i}]", named: false, building: b.Size);
                budget.Leave(named: false);
            }
        });
        Assert.Contains("more than 64 bytes", e.Message);
    }
}
